+import { expect, test } from '@jest/globals';
+import { resolvePeers } from '../lib/resolvePeers.js';
+test('packages are not deduplicated when versions do not match', async ()=>{
+    const fooPkg = {
+        name: 'foo',
+        version: '1.0.0',
+        pkgIdWithPatchHash: 'foo/1.0.0',
+        id: '',
+        peerDependencies: {
+            bar: {
+                version: '1.0.0 || 2.0.0'
+            },
+            baz: {
+                version: '1.0.0 || 2.0.0',
+                optional: true
+            }
+        }
+    };
+    const peers = Object.fromEntries([
+        [
+            'bar',
+            '1.0.0'
+        ],
+        [
+            'bar',
+            '2.0.0'
+        ],
+        [
+            'baz',
+            '1.0.0'
+        ],
+        [
+            'baz',
+            '2.0.0'
+        ]
+    ].map(([name, version])=>[
+            `${name}_${version.replace(/\./g, '_')}`,
+            {
+                name,
+                version,
+                pkgIdWithPatchHash: `${name}/${version}`,
+                peerDependencies: {},
+                id: ''
+            }
+        ]));
+    const { dependenciesByProjectId } = await resolvePeers({
+        allPeerDepNames: new Set([
+            'bar',
+            'baz'
+        ]),
+        projects: [
+            {
+                directNodeIdsByAlias: new Map([
+                    [
+                        'foo',
+                        '>project1>foo/1.0.0>'
+                    ],
+                    [
+                        'bar',
+                        '>project1>bar/1.0.0>'
+                    ]
+                ]),
+                topParents: [],
+                rootDir: '',
+                id: 'project1'
+            },
+            {
+                directNodeIdsByAlias: new Map([
+                    [
+                        'foo',
+                        '>project2>foo/1.0.0>'
+                    ],
+                    [
+                        'bar',
+                        '>project2>bar/1.0.0>'
+                    ],
+                    [
+                        'baz',
+                        '>project2>baz/1.0.0>'
+                    ]
+                ]),
+                topParents: [],
+                rootDir: '',
+                id: 'project2'
+            },
+            {
+                directNodeIdsByAlias: new Map([
+                    [
+                        'foo',
+                        '>project3>foo/1.0.0>'
+                    ],
+                    [
+                        'bar',
+                        '>project3>bar/2.0.0>'
+                    ]
+                ]),
+                topParents: [],
+                rootDir: '',
+                id: 'project3'
+            },
+            {
+                directNodeIdsByAlias: new Map([
+                    [
+                        'foo',
+                        '>project4>foo/1.0.0>'
+                    ],
+                    [
+                        'bar',
+                        '>project4>bar/2.0.0>'
+                    ],
+                    [
+                        'baz',
+                        '>project4>baz/2.0.0>'
+                    ]
+                ]),
+                topParents: [],
+                rootDir: '',
+                id: 'project4'
+            }
+        ],
+        resolvedImporters: {},
+        dependenciesTree: new Map([
+            [
+                '>project1>foo/1.0.0>',
+                fooPkg
+            ],
+            [
+                '>project1>bar/1.0.0>',
+                peers.bar_1_0_0
+            ],
+            [
+                '>project2>foo/1.0.0>',
+                fooPkg
+            ],
+            [
+                '>project2>bar/1.0.0>',
+                peers.bar_1_0_0
+            ],
+            [
+                '>project2>baz/1.0.0>',
+                peers.baz_1_0_0
+            ],
+            [
+                '>project3>foo/1.0.0>',
+                fooPkg
+            ],
+            [
+                '>project3>bar/2.0.0>',
+                peers.bar_2_0_0
+            ],
+            [
+                '>project4>foo/1.0.0>',
+                fooPkg
+            ],
+            [
+                '>project4>bar/2.0.0>',
+                peers.bar_2_0_0
+            ],
+            [
+                '>project4>baz/2.0.0>',
+                peers.baz_2_0_0
+            ]
+        ].map(([path, resolvedPackage])=>[
+                path,
+                {
+                    children: {},
+                    installable: {},
+                    resolvedPackage,
+                    depth: 0
+                }
+            ])),
+        dedupePeerDependents: true,
+        virtualStoreDir: '',
+        virtualStoreDirMaxLength: 120,
+        lockfileDir: '',
+        peersSuffixMaxLength: 1000,
+        workspaceProjectIds: new Set()
+    });
+    expect(dependenciesByProjectId.project1.get('foo')).toEqual(dependenciesByProjectId.project2.get('foo'));
+    expect(dependenciesByProjectId.project1.get('foo')).not.toEqual(dependenciesByProjectId.project3.get('foo'));
+    expect(dependenciesByProjectId.project3.get('foo')).toEqual(dependenciesByProjectId.project4.get('foo'));
+});
+
+//# sourceMappingURL=data:application/json;base64,
