+import { createShortHash } from '@pnpm/crypto.hash';
+import semver from 'semver';
+export function isAbsolute(dependencyPath) {
+  return dependencyPath[0] !== '/';
+}
+export function indexOfDepPathSuffix(depPath) {
+  if (!depPath.endsWith(')')) return {
+    peersIndex: -1,
+    patchHashIndex: -1
+  };
