+    expect(replaceVersionInBareSpecifier('file:./pkg', '1.1.0')).toBe('file:./pkg');
+    expect(replaceVersionInBareSpecifier('link:../pkg', '1.1.0')).toBe('link:../pkg');
+    expect(replaceVersionInBareSpecifier('catalog:', '1.1.0')).toBe('catalog:');
