+fdcc690d71a6e2b1b157c803a25ace4e
+import { expect, test } from '@jest/globals';
+import { getManifestFromResponse } from '../lib/resolveDependencies.js';
+test('getManifestFromResponse returns manifest from pkgResponse when available', ()=>{
+    const pkgResponse = {
+        body: {
+            manifest: {
+                name: 'foo',
+                version: '1.0.0'
+            }
+        }
+    };
+    const wantedDependency = {
+        alias: 'foo',
+        bareSpecifier: 'foo',
+        dev: false,
+        optional: false
+    };
+    const result = getManifestFromResponse(pkgResponse, wantedDependency);
+    expect(result).toEqual({
+        name: 'foo',
+        version: '1.0.0'
+    });
+});
+test('getManifestFromResponse returns currentPkg info when manifest is undefined', ()=>{
+    const pkgResponse = {
+        body: {
+            manifest: undefined
+        }
+    };
+    const wantedDependency = {
+        alias: 'node',
+        bareSpecifier: 'runtime:^22.0.0',
+        dev: false,
+        optional: false
+    };
+    const currentPkg = {
+        name: 'node',
+        version: '22.20.0'
+    };
+    const result = getManifestFromResponse(pkgResponse, wantedDependency, currentPkg);
+    expect(result).toEqual({
+        name: 'node',
+        version: '22.20.0'
+    });
+});
+test('getManifestFromResponse returns default 0.0.0 when manifest and currentPkg are unavailable', ()=>{
+    const pkgResponse = {
+        body: {
+            manifest: undefined
+        }
+    };
+    const wantedDependency = {
+        alias: 'foo',
+        bareSpecifier: 'foo@^1.0.0',
+        dev: false,
+        optional: false
+    };
+    const result = getManifestFromResponse(pkgResponse, wantedDependency);
+    expect(result).toEqual({
+        name: 'foo',
+        version: '0.0.0'
+    });
+});
+test('getManifestFromResponse extracts name from bareSpecifier when no alias', ()=>{
+    const pkgResponse = {
+        body: {
+            manifest: undefined
+        }
+    };
+    const wantedDependency = {
+        bareSpecifier: '@scope/package@^1.0.0',
+        dev: false,
+        optional: false
+    };
+    const result = getManifestFromResponse(pkgResponse, wantedDependency);
+    expect(result).toEqual({
+        name: 'package@^1.0.0',
+        version: '0.0.0'
+    });
+});
+test('getManifestFromResponse does not use currentPkg when only name is available', ()=>{
+    const pkgResponse = {
+        body: {
+            manifest: undefined
+        }
+    };
+    const wantedDependency = {
+        alias: 'foo',
+        bareSpecifier: 'foo',
+        dev: false,
+        optional: false
+    };
+    const currentPkg = {
+        name: 'foo',
+        version: undefined
+    };
+    const result = getManifestFromResponse(pkgResponse, wantedDependency, currentPkg);
+    expect(result).toEqual({
+        name: 'foo',
+        version: '0.0.0'
+    });
+});
+test('getManifestFromResponse does not use currentPkg when only version is available', ()=>{
+    const pkgResponse = {
+        body: {
+            manifest: undefined
+        }
+    };
+    const wantedDependency = {
+        alias: 'foo',
+        bareSpecifier: 'foo',
+        dev: false,
+        optional: false
+    };
+    const currentPkg = {
+        name: undefined,
+        version: '1.0.0'
+    };
+    const result = getManifestFromResponse(pkgResponse, wantedDependency, currentPkg);
+    expect(result).toEqual({
+        name: 'foo',
+        version: '0.0.0'
+    });
+});
+
